# DK GRD.  Gram - Rødding
#
let gr = path("d3.dk.grd");

with detail = 3, railway = :first :g1000 :pax :removed {
    # point.dk.Gram  dk.HVA

    with link = "line.dk.GRD" {
        track(gr[:gra.yr, :las - 0.49sw]);
    }

    with link = "point.dk.Låsled" {
        track(gr[:las - 0.5sw, :las + 0.5sw]);
        marker(:right :de.hp, gr[:las] >> 0.5lt);
        slabel(:left, gr[:las] << 0.5lt + (-1dt, 1dt), "Låsled");
    }

    with link = "line.dk.GRD" {
        track(gr[:las + 0.49sw, :bra - 0.49sw]);
    }

    with link = "point.dk.Brændstrup" {
        track(gr[:bra - 0.5sw, :bra + 0.5sw]);
        marker(:right :de.bf, gr[:bra] >> 0.7lt);
        slabel(:right, gr[:bra] >> 0.5lt >> 1sh + (1.3dt, 1.1dt),
            "Brændstrup"
        );
    }

    with link = "line.dk.GRD" {
        track(gr[:bra + 0.49sw, :bra + 0.81km]);
        line_label(:left:e, gr[:bra + 0.8km] << 0.5lt, "GRD");
        track(gr[:bra + 0.79km, :rod - 0.49sw]);
    }

    with link = "point.dk.Rødding" {
        track(gr[:rod - 0.5sw, :rod + 0.5sw]);
        marker(:right :de.bf, gr[:rod] >> 0.7lt);
        slabel(:top :bold, gr[:rod] << 0.5lt << 0.5dt,
            "Rødding"
        );
    }
}

